      <tr><td class="num">KD4X8X4</td><td class="num">4 in.</td><td class="num">114.3 mm</td><td class="num">DN 100</td><td class="num">110 mm</td><td class="num">55–109</td><td class="num">15.1–30.3</td></tr>
